// The web client's only way to the server (docs/ARCHITECTURE.md §9.2). The SPA is a client of the public API (D39):
// every path is relative to API_BASE, requests are same-origin with the session cookie, and no request ever carries an
// `Authorization` header. Types come from ./gen (generated by ts-rs; never edit them).
import type { ErrorBody } from './gen/ErrorBody';
import type { ErrorCode } from './gen/ErrorCode';

export const API_BASE = '/api/v1';

/** Sent on `window` when a request answers 401 (except failed sign-ins): opens the sign-in dialog in place. */
export const AUTH_LOST_EVENT = 'auth-lost';

export type Method = 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE';

/**
 * An error code: a server `ErrorCode`, any code a newer server adds (clients treat an unknown code by its status,
 * §7.1), or one of the client's own: `network` (no response at all: offline, DNS, connection reset) and
 * `bad_response` (a response that is not the JSON error envelope, e.g. a proxy's 502 page).
 */
export type ApiErrorCode = ErrorCode | 'network' | 'bad_response' | (string & {});

export class ApiError extends Error {
  /** The HTTP status; 0 for `network`. */
  readonly status: number;
  readonly code: ApiErrorCode;
  /** The per-code `details` object of the envelope, if any. */
  readonly details: unknown;
  /** The envelope's `request_id` (or the `X-Request-Id` header); null without a response. */
  readonly requestId: string | null;

  constructor(status: number, code: ApiErrorCode, message: string, details?: unknown, requestId?: string | null) {
    super(message);
    this.name = 'ApiError';
    this.status = status;
    this.code = code;
    this.details = details;
    this.requestId = requestId ?? null;
  }
}

/** `e` is an ApiError (with that code, when given). */
export function isApiError<C extends ApiErrorCode = ApiErrorCode>(e: unknown, code?: C): e is ApiError & { code: C } {
  return e instanceof ApiError && (code === undefined || e.code === code);
}

export interface ApiOptions {
  /** A JSON body (sent as `application/json`). */
  json?: unknown;
  /** A raw body; sent as `application/octet-stream` unless `headers` names a `Content-Type` (§7.1 media types). */
  body?: BodyInit | null;
  /** Extra request headers (`If-Match`, `Content-Type: text/markdown`, …). `Authorization` is always dropped. */
  headers?: Record<string, string>;
  /** Sends `If-None-Match: <etag>`; a 304 then resolves with no data (`apiResponse` gives the response's ETag). */
  etag?: string;
  signal?: AbortSignal;
  /** `fetch(…, {keepalive})`, for the doc session's flush on `pagehide` (§9.4). */
  keepalive?: boolean;
  /** Default true. False for requests whose 401 is an answer, not a lost session (AuthGate's `/auth/me`). */
  authLost?: boolean;
}

export interface ApiResponse<T> {
  status: number;
  /** The parsed body: JSON, text for `text/*`, a Blob otherwise; undefined for 204 and 304. */
  data: T;
  /** The response's `ETag` header, exactly as sent. */
  etag: string | null;
  notModified: boolean;
  headers: Headers;
}

/** The full URL of an API path: `apiUrl('/items/x')` is `/api/v1/items/x`. */
export function apiUrl(path: string): string {
  if (!path.startsWith('/')) throw new TypeError(`API paths start with "/": ${path}`);
  return API_BASE + path;
}

/** Like `api`, but returns the status and headers too and resolves a 304 instead of returning undefined data. */
export async function apiResponse<T>(method: Method, path: string, opts: ApiOptions = {}): Promise<ApiResponse<T>> {
  const headers = new Headers(opts.headers);
  headers.delete('Authorization');
  let body: BodyInit | null | undefined;
  if (opts.json !== undefined) {
    headers.set('Content-Type', 'application/json');
    body = JSON.stringify(opts.json);
  } else if (opts.body !== undefined && opts.body !== null) {
    if (!headers.has('Content-Type')) headers.set('Content-Type', 'application/octet-stream');
    body = opts.body;
  }
  if (opts.etag !== undefined) headers.set('If-None-Match', opts.etag);

  let res: Response;
  try {
    res = await fetch(apiUrl(path), {
      method,
      headers,
      body,
      credentials: 'same-origin',
      signal: opts.signal,
      keepalive: opts.keepalive,
    });
  } catch (e) {
    if (opts.signal?.aborted) throw e;
    throw new ApiError(0, 'network', e instanceof Error ? e.message : 'Network error');
  }

  const etag = res.headers.get('ETag');
  if (res.status === 304) {
    return { status: 304, data: undefined as T, etag, notModified: true, headers: res.headers };
  }
  if (!res.ok) throw await toApiError(res, opts.authLost ?? true);
  if (res.status === 204) {
    return { status: 204, data: undefined as T, etag, notModified: false, headers: res.headers };
  }
  const type = res.headers.get('Content-Type') ?? '';
  let data: unknown;
  try {
    if (type.includes('json')) data = await res.json();
    else if (type.startsWith('text/')) data = await res.text();
    else data = await res.blob();
  } catch (e) {
    throw new ApiError(res.status, 'bad_response', e instanceof Error ? e.message : 'Unreadable response',
      undefined, res.headers.get('X-Request-Id'));
  }
  return { status: res.status, data: data as T, etag, notModified: false, headers: res.headers };
}

/**
 * Calls the API and returns the parsed body; throws `ApiError` for every error status and for network failures.
 * 204 resolves to undefined. With `etag`, a 304 resolves to undefined: keep the cached value.
 */
export function api<T>(method: Method, path: string, opts: ApiOptions & { etag: string }): Promise<T | undefined>;
export function api<T>(method: Method, path: string, opts?: ApiOptions): Promise<T>;
export async function api<T>(method: Method, path: string, opts: ApiOptions = {}): Promise<T | undefined> {
  return (await apiResponse<T>(method, path, opts)).data;
}

async function toApiError(res: Response, authLost: boolean): Promise<ApiError> {
  const headerId = res.headers.get('X-Request-Id');
  let err: ApiError;
  try {
    const body = (await res.json()) as Partial<ErrorBody> | null;
    const info = body?.error;
    if (info && typeof info.code === 'string') {
      err = new ApiError(res.status, info.code, info.message ?? info.code, info.details ?? undefined,
        body?.request_id ?? headerId);
    } else {
      err = new ApiError(res.status, 'bad_response', `HTTP ${res.status}`, undefined, headerId);
    }
  } catch {
    err = new ApiError(res.status, 'bad_response', `HTTP ${res.status}`, undefined, headerId);
  }
  if (res.status === 401 && authLost && err.code !== 'invalid_credentials' && typeof window !== 'undefined') {
    window.dispatchEvent(new CustomEvent(AUTH_LOST_EVENT, { detail: err }));
  }
  return err;
}
